import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;

public class Main {

    public static void main(String[] args) {
        String inputString = "<html><head><title>Example</title></head><body>Hello World!</body></html>";
        Document doc = Jsoup.parse(inputString);

        // Find the <title> element
        Element titleElement = doc.selectFirst("title");
        if (titleElement != null) {
            System.out.println(titleElement.text());
        } else {
            System.out.println("No <title> element found.");
        }

        // Find all links on the page
        Document linkDoc = doc.select("a[href]");
        for (Element link : linkDoc) {
            System.out.println(link.attr("href"));
        }

        // Find the first paragraph element with text content
        Element paragraphElement = doc.selectFirst("p");
        if (paragraphElement != null && !paragraphElement.text().isEmpty()) {
            System.out.println(paragraphElement.text());
        } else {
            System.out.println("No paragraph element found.");
        }
    }
}
```

